/**
 * F42: Deal Curation and Editorial Collections (Tier P2)
 *
 * Requirements:
 * - Solution: Human-reviewable collections based on evidence, freshness and expiry.
 * - Acceptance Invariant: No fabricated scarcity or unsupported featured discount.
 */

export class FabricatedScarcityError extends Error {
  constructor(message: string) {
    super(`[F42_FABRICATED_SCARCITY_VIOLATION] ${message}`);
    this.name = 'FabricatedScarcityError';
  }
}

export class UnsupportedFeaturedDiscountError extends Error {
  constructor(message: string) {
    super(`[F42_UNSUPPORTED_DISCOUNT_VIOLATION] ${message}`);
    this.name = 'UnsupportedFeaturedDiscountError';
  }
}

export class StaleCuratedItemError extends Error {
  constructor(message: string) {
    super(`[F42_STALE_CURATED_ITEM_VIOLATION] ${message}`);
    this.name = 'StaleCuratedItemError';
  }
}

export type CollectionTheme =
  | 'WEEKEND_GETAWAY'
  | 'FAMILY_HOLIDAY'
  | 'TET_PEAK_SAVINGS'
  | 'BEACH_AND_ISLANDS'
  | 'BUDGET_DISCOVERY';

export interface CuratorMetadata {
  curatorId: string;
  name: string;
  role: string;
  signedAt: string; // ISO 8601
}

export interface CuratedDealInput {
  dealId: string;
  originCode: string;
  destinationCode: string;
  airlineCode: string;
  advertisedPriceVND: number;
  cohortMedianPriceVND: number;
  claimedDiscountPercent?: number;
  observedAt: string; // ISO 8601
  scarcityClaim?: {
    seatsRemaining?: number;
    claimTextVi: string;
    hasProviderInventoryProof: boolean;
  };
  editorNotesVi: string;
}

export interface ValidatedCuratedItem {
  dealId: string;
  routeKey: string;
  airlineCode: string;
  advertisedPriceVND: number;
  cohortMedianPriceVND: number;
  calculatedDiscountPercent: number;
  hasVerifiedScarcity: boolean;
  scarcityLabelVi?: string;
  editorNotesVi: string;
  observedAt: string;
}

export interface EditorialCollection {
  collectionId: string;
  titleVi: string;
  summaryVi: string;
  theme: CollectionTheme;
  curator: CuratorMetadata;
  expiresAt: string; // ISO 8601
  items: ValidatedCuratedItem[];
  isCurrentlyActive: boolean;
  totalDealsCount: number;
}

const MAX_DEAL_AGE_HOURS_FOR_EDITORIAL = 48;

/**
 * Validates curated deal items against authentic observation evidence.
 * Enforces strict anti-fabrication invariants (F42).
 */
export function validateAndPublishEditorialCollection(params: {
  collectionId: string;
  titleVi: string;
  summaryVi: string;
  theme: CollectionTheme;
  curator: CuratorMetadata;
  expiresAt: string;
  items: CuratedDealInput[];
  nowIsoString?: string;
}): EditorialCollection {
  const {
    collectionId,
    titleVi,
    summaryVi,
    theme,
    curator,
    expiresAt,
    items,
    nowIsoString = new Date().toISOString(),
  } = params;

  if (!items || items.length === 0) {
    throw new Error('Editorial collection must contain at least one curated item.');
  }

  const nowMs = new Date(nowIsoString).getTime();
  const expiresMs = new Date(expiresAt).getTime();

  if (expiresMs <= new Date(curator.signedAt).getTime()) {
    throw new Error('Collection expiration must be strictly after curator signature timestamp.');
  }

  const validatedItems: ValidatedCuratedItem[] = items.map((item) => {
    // 1. Freshness check: Reject obsolete deals (> 48h old)
    const itemObservedMs = new Date(item.observedAt).getTime();
    const ageHours = (nowMs - itemObservedMs) / (1000 * 60 * 60);
    if (ageHours > MAX_DEAL_AGE_HOURS_FOR_EDITORIAL) {
      throw new StaleCuratedItemError(
        `Deal ${item.dealId} (${item.originCode}-${item.destinationCode}) was observed ${Math.round(ageHours)}h ago, exceeding the ${MAX_DEAL_AGE_HOURS_FOR_EDITORIAL}h editorial freshness ceiling.`
      );
    }

    // 2. Discount validity check: Verify claimed discount does not exceed authentic calculation
    const trueDiscountPercent = Math.max(
      0,
      Math.round(
        ((item.cohortMedianPriceVND - item.advertisedPriceVND) / item.cohortMedianPriceVND) * 100
      )
    );

    if (item.claimedDiscountPercent !== undefined) {
      // Claiming higher discount than authentic data permits (> 1% tolerance for rounding)
      if (item.claimedDiscountPercent > trueDiscountPercent + 1) {
        throw new UnsupportedFeaturedDiscountError(
          `Deal ${item.dealId} claims discount of ${item.claimedDiscountPercent}% but authentic cohort calculation only supports ${trueDiscountPercent}% (Price: ${item.advertisedPriceVND}₫ vs Cohort: ${item.cohortMedianPriceVND}₫).`
        );
      }
    }

    // 3. Scarcity claims check: Forbid fake urgency without inventory evidence
    let hasVerifiedScarcity = false;
    let scarcityLabelVi: string | undefined;

    if (item.scarcityClaim) {
      if (!item.scarcityClaim.hasProviderInventoryProof) {
        throw new FabricatedScarcityError(
          `Deal ${item.dealId} asserts scarcity claim "${item.scarcityClaim.claimTextVi}" without provider inventory proof.`
        );
      }
      hasVerifiedScarcity = true;
      scarcityLabelVi = item.scarcityClaim.claimTextVi;
    }

    return {
      dealId: item.dealId,
      routeKey: `${item.originCode}-${item.destinationCode}`,
      airlineCode: item.airlineCode,
      advertisedPriceVND: item.advertisedPriceVND,
      cohortMedianPriceVND: item.cohortMedianPriceVND,
      calculatedDiscountPercent: trueDiscountPercent,
      hasVerifiedScarcity,
      scarcityLabelVi,
      editorNotesVi: item.editorNotesVi,
      observedAt: item.observedAt,
    };
  });

  const isCurrentlyActive = nowMs < expiresMs;

  return {
    collectionId,
    titleVi,
    summaryVi,
    theme,
    curator,
    expiresAt,
    items: validatedItems,
    isCurrentlyActive,
    totalDealsCount: validatedItems.length,
  };
}

import { describe, expect, it } from 'vitest';
import {
  validateAndPublishEditorialCollection,
  FabricatedScarcityError,
  UnsupportedFeaturedDiscountError,
  StaleCuratedItemError,
  EditorialCollection,
  CuratorMetadata,
} from './editorialCollections';

describe('F42: Deal Curation and Editorial Collections', () => {
  const mockCurator: CuratorMetadata = {
    curatorId: 'curator_01',
    name: 'Nguyễn Văn A',
    role: 'Lead Flight Analyst',
    signedAt: '2026-10-15T00:00:00Z',
  };

  const validDealItem = {
    dealId: 'deal_sgn_han_01',
    originCode: 'SGN',
    destinationCode: 'HAN',
    airlineCode: 'VJ',
    advertisedPriceVND: 1_200_000,
    cohortMedianPriceVND: 2_000_000, // 40% discount
    claimedDiscountPercent: 40,
    observedAt: '2026-10-15T02:00:00Z',
    editorNotesVi: 'Giá tốt cho chặng SGN-HAN vào khung giờ sáng sớm.',
  };

  it('publishes a valid evidence-grounded collection with authentic discount calculation', () => {
    const result: EditorialCollection = validateAndPublishEditorialCollection({
      collectionId: 'col_weekend_01',
      titleVi: 'Vé tốt cuối tuần đi Hà Nội',
      summaryVi: 'Tổng hợp các chuyến bay khởi hành sớm với mức giá tốt nhất.',
      theme: 'WEEKEND_GETAWAY',
      curator: mockCurator,
      expiresAt: '2026-10-18T00:00:00Z',
      items: [validDealItem],
      nowIsoString: '2026-10-15T04:00:00Z',
    });

    expect(result.collectionId).toBe('col_weekend_01');
    expect(result.isCurrentlyActive).toBe(true);
    expect(result.items[0].calculatedDiscountPercent).toBe(40);
    expect(result.items[0].hasVerifiedScarcity).toBe(false);
  });

  it('allows verified scarcity when provider inventory proof is provided', () => {
    const result = validateAndPublishEditorialCollection({
      collectionId: 'col_weekend_02',
      titleVi: 'Vé giới hạn có bằng chứng',
      summaryVi: 'Chỉ còn số lượng ghế ít đã được hãng xác nhận.',
      theme: 'BUDGET_DISCOVERY',
      curator: mockCurator,
      expiresAt: '2026-10-18T00:00:00Z',
      items: [
        {
          ...validDealItem,
          scarcityClaim: {
            seatsRemaining: 2,
            claimTextVi: 'Còn 2 ghế giá này trên hệ thống',
            hasProviderInventoryProof: true,
          },
        },
      ],
      nowIsoString: '2026-10-15T04:00:00Z',
    });

    expect(result.items[0].hasVerifiedScarcity).toBe(true);
    expect(result.items[0].scarcityLabelVi).toBe('Còn 2 ghế giá này trên hệ thống');
  });

  it('throws FabricatedScarcityError when scarcity claim lacks provider inventory proof', () => {
    expect(() =>
      validateAndPublishEditorialCollection({
        collectionId: 'col_fake_scarcity',
        titleVi: 'Bộ sưu tập giả mạo độ khan hiếm',
        summaryVi: 'Cố tình tạo sự khẩn cấp giả tạo để ép khách mua.',
        theme: 'LAST_MINUTE_BUDGET' as any,
        curator: mockCurator,
        expiresAt: '2026-10-18T00:00:00Z',
        items: [
          {
            ...validDealItem,
            scarcityClaim: {
              seatsRemaining: 1,
              claimTextVi: 'Chỉ còn duy nhất 1 vé! Nhanh tay kẻo lỡ!',
              hasProviderInventoryProof: false, // FAKE SCARCITY!
            },
          },
        ],
        nowIsoString: '2026-10-15T04:00:00Z',
      })
    ).toThrow(FabricatedScarcityError);
  });

  it('throws UnsupportedFeaturedDiscountError when claimed discount exaggerates true cohort calculation', () => {
    expect(() =>
      validateAndPublishEditorialCollection({
        collectionId: 'col_fake_discount',
        titleVi: 'Giảm giá thổi phồng',
        summaryVi: 'Quảng cáo giảm 70% nhưng thực tế đối sánh chỉ giảm 40%.',
        theme: 'BUDGET_DISCOVERY',
        curator: mockCurator,
        expiresAt: '2026-10-18T00:00:00Z',
        items: [
          {
            ...validDealItem,
            advertisedPriceVND: 1_200_000,
            cohortMedianPriceVND: 2_000_000, // Actual discount: (2M - 1.2M) / 2M = 40%
            claimedDiscountPercent: 70, // FRAUDULENT 70% CLAIM!
          },
        ],
        nowIsoString: '2026-10-15T04:00:00Z',
      })
    ).toThrow(UnsupportedFeaturedDiscountError);
  });

  it('throws StaleCuratedItemError when deal observation age exceeds 48 hours', () => {
    expect(() =>
      validateAndPublishEditorialCollection({
        collectionId: 'col_stale',
        titleVi: 'Vé cũ quá hạn',
        summaryVi: 'Vé đã quét từ 3 ngày trước nhưng vẫn cố đưa vào bộ sưu tập tươi mới.',
        theme: 'BEACH_AND_ISLANDS',
        curator: mockCurator,
        expiresAt: '2026-10-18T00:00:00Z',
        items: [
          {
            ...validDealItem,
            observedAt: '2026-10-11T00:00:00Z', // 4 days ago
          },
        ],
        nowIsoString: '2026-10-15T04:00:00Z',
      })
    ).toThrow(StaleCuratedItemError);
  });

  it('marks isCurrentlyActive = false if collection expiration has passed', () => {
    const result = validateAndPublishEditorialCollection({
      collectionId: 'col_expired',
      titleVi: 'Bộ sưu tập đã hết hạn',
      summaryVi: 'Bộ sưu tập của tuần trước.',
      theme: 'WEEKEND_GETAWAY',
      curator: {
        ...mockCurator,
        signedAt: '2026-10-01T00:00:00Z',
      },
      expiresAt: '2026-10-10T00:00:00Z', // Expired
      items: [validDealItem],
      nowIsoString: '2026-10-15T04:00:00Z',
    });

    expect(result.isCurrentlyActive).toBe(false);
  });
});

