/**
 * F43: Direct/Affiliate Provider Comparison (Tier P2)
 *
 * Requirements:
 * - Solution: Compare actual provider quote basis, refresh state, link class, partner rights and disclosures.
 * - Acceptance Invariant: Commercial ranking does not override undisclosed objective cheapest result.
 */

export class CommercialRankingOverrideError extends Error {
  constructor(message: string) {
    super(`[F43_COMMERCIAL_RANKING_OVERRIDE_VIOLATION] ${message}`);
    this.name = 'CommercialRankingOverrideError';
  }
}

export type ProviderChannelType =
  | 'DIRECT_AIRLINE'        // Direct airline official website
  | 'OTA_PARTNER'          // Online Travel Agent (Traveloka, Trip.com, etc.)
  | 'AFFILIATE_AGGREGATOR'; // Metasearch / affiliate referral (Skyscanner, Kayak, etc.)

export type QuoteBasis =
  | 'BASE_FARE_ONLY'
  | 'TOTAL_INCLUSIVE_NO_BAGGAGE'
  | 'ALL_INCLUSIVE_WITH_BAGGAGE';

export type DeepLinkClass =
  | 'DEEP_LINK_EXACT_OFFER'   // Deep links directly to checkout/fare summary
  | 'SEARCH_RESULTS_PREFILLED'// Pre-fills origin, destination, dates, passengers
  | 'PROVIDER_HOMEPAGE_GENERIC'; // Generic fallback homepage

export interface ProviderQuoteInput {
  providerId: string;
  providerName: string;
  channelType: ProviderChannelType;
  quoteBasis: QuoteBasis;
  rawQuotedPriceVND: number;
  mandatoryTaxesAndFeesVND: number;
  checkedBaggageFeeVND: number;
  isBaggageIncludedInQuote: boolean;
  deepLinkClass: DeepLinkClass;
  deepLinkUrl: string;
  isCommercialPartner: boolean;
  affiliateCommissionRatePercent?: number; // e.g., 3.5%
  observedAt: string; // ISO 8601
}

export interface NormalizedProviderChannel {
  providerId: string;
  providerName: string;
  channelType: ProviderChannelType;
  quoteBasis: QuoteBasis;
  rawQuotedPriceVND: number;
  normalizedTotalCostVND: number;
  breakdown: {
    baseFareVND: number;
    mandatoryTaxesAndFeesVND: number;
    baggageFeeVND: number;
  };
  isObjectiveCheapest: boolean;
  commercialStatusVi: string;
  deepLinkClass: DeepLinkClass;
  deepLinkUrl: string;
  stalenessMinutes: number;
}

export interface DirectAffiliateComparisonResult {
  flightKey: string;
  channels: NormalizedProviderChannel[];
  objectiveCheapestProviderId: string;
  directAirlineProviderId?: string;
  cheapestChannelSavingsVsDirectVND: number;
  disclosureNoticeVi: string;
}

/**
 * Normalizes provider quotes across direct and affiliate channels.
 * Enforces strict invariant: Commercial ranking can NEVER override
 * or misrepresent the objective cheapest result (F43).
 */
export function compareProviderChannels(params: {
  flightKey: string;
  quotes: ProviderQuoteInput[];
  requiresCheckedBaggage?: boolean;
  nowIsoString?: string;
}): DirectAffiliateComparisonResult {
  const { flightKey, quotes, requiresCheckedBaggage = false, nowIsoString = new Date().toISOString() } = params;

  if (!quotes || quotes.length === 0) {
    throw new Error('At least one provider quote is required for channel comparison.');
  }

  const nowMs = new Date(nowIsoString).getTime();

  // 1. Calculate normalized total cost for each channel
  const normalizedList: NormalizedProviderChannel[] = quotes.map((q) => {
    let baseFare = q.rawQuotedPriceVND;
    let taxes = q.mandatoryTaxesAndFeesVND;
    let baggage = 0;
    let totalCost = 0;

    if (q.quoteBasis === 'BASE_FARE_ONLY') {
      baseFare = q.rawQuotedPriceVND;
      taxes = q.mandatoryTaxesAndFeesVND;
      if (requiresCheckedBaggage && !q.isBaggageIncludedInQuote) {
        baggage = q.checkedBaggageFeeVND;
      }
      totalCost = baseFare + taxes + baggage;
    } else if (q.quoteBasis === 'TOTAL_INCLUSIVE_NO_BAGGAGE') {
      // Raw price already includes mandatory taxes and fees
      taxes = q.mandatoryTaxesAndFeesVND;
      baseFare = Math.max(0, q.rawQuotedPriceVND - taxes);
      if (requiresCheckedBaggage && !q.isBaggageIncludedInQuote) {
        baggage = q.checkedBaggageFeeVND;
      }
      totalCost = q.rawQuotedPriceVND + baggage;
    } else {
      // ALL_INCLUSIVE_WITH_BAGGAGE: already includes taxes and baggage
      taxes = q.mandatoryTaxesAndFeesVND;
      const includedBaggage = q.isBaggageIncludedInQuote ? q.checkedBaggageFeeVND : 0;
      baggage = includedBaggage;
      baseFare = Math.max(0, q.rawQuotedPriceVND - taxes - baggage);
      totalCost = q.rawQuotedPriceVND;
    }

    const stalenessMinutes = Math.max(
      0,
      Math.round((nowMs - new Date(q.observedAt).getTime()) / (1000 * 60))
    );

    let commercialStatusVi = 'Kênh bán trực tiếp chính thức';
    if (q.channelType === 'OTA_PARTNER') {
      commercialStatusVi = q.isCommercialPartner
        ? 'Đại lý du lịch trực tuyến (Đối tác thương mại Farely)'
        : 'Đại lý du lịch trực tuyến (Khách quan)';
    } else if (q.channelType === 'AFFILIATE_AGGREGATOR') {
      commercialStatusVi = 'Kênh đối sánh liên kết (Affiliate)';
    }

    return {
      providerId: q.providerId,
      providerName: q.providerName,
      channelType: q.channelType,
      quoteBasis: q.quoteBasis,
      rawQuotedPriceVND: q.rawQuotedPriceVND,
      normalizedTotalCostVND: totalCost,
      breakdown: {
        baseFareVND: baseFare,
        mandatoryTaxesAndFeesVND: taxes,
        baggageFeeVND: baggage,
      },
      isObjectiveCheapest: false, // will mark below
      commercialStatusVi,
      deepLinkClass: q.deepLinkClass,
      deepLinkUrl: q.deepLinkUrl,
      stalenessMinutes,
    };
  });

  // 2. Identify the mathematical objective cheapest total cost
  let minCost = Infinity;
  for (const c of normalizedList) {
    if (c.normalizedTotalCostVND < minCost) {
      minCost = c.normalizedTotalCostVND;
    }
  }

  // Mark all channels achieving the minimum cost
  for (const c of normalizedList) {
    if (c.normalizedTotalCostVND === minCost) {
      c.isObjectiveCheapest = true;
    }
  }

  const cheapestChannels = normalizedList.filter((c) => c.isObjectiveCheapest);
  const objectiveCheapestProviderId = cheapestChannels[0].providerId;

  // Find direct airline if available
  const directAirline = normalizedList.find((c) => c.channelType === 'DIRECT_AIRLINE');
  const cheapestChannelSavingsVsDirectVND = directAirline
    ? Math.max(0, directAirline.normalizedTotalCostVND - minCost)
    : 0;

  // 3. Sort channels objectively by normalized total cost (cheapest first)
  // Strict F43 invariant: Do NOT sort by affiliate commission or partner status!
  normalizedList.sort((a, b) => a.normalizedTotalCostVND - b.normalizedTotalCostVND);

  return {
    flightKey,
    channels: normalizedList,
    objectiveCheapestProviderId,
    directAirlineProviderId: directAirline?.providerId,
    cheapestChannelSavingsVsDirectVND,
    disclosureNoticeVi:
      'Farely đối sánh độc lập giữa website hãng hàng không và các đại lý. Thứ tự hiển thị luôn ưu tiên chi phí thực tế thấp nhất, hoàn toàn không bị thao túng bởi hoa hồng hay phí đối tác.',
  };
}

/**
 * Validates that an advertised "Cheapest" badge or display order complies with F43.
 * Throws CommercialRankingOverrideError if a partner was prioritized over a cheaper option.
 */
export function assertCommercialRankingIntegrity(
  promotedProviderId: string,
  comparison: DirectAffiliateComparisonResult
): void {
  const promotedChannel = comparison.channels.find((c) => c.providerId === promotedProviderId);
  if (!promotedChannel) {
    throw new CommercialRankingOverrideError(`Promoted provider ${promotedProviderId} not found in channel comparison.`);
  }

  const trueCheapest = comparison.channels.find((c) => c.isObjectiveCheapest);
  if (trueCheapest && promotedChannel.normalizedTotalCostVND > trueCheapest.normalizedTotalCostVND) {
    throw new CommercialRankingOverrideError(
      `Provider "${promotedChannel.providerName}" (${promotedChannel.normalizedTotalCostVND}₫) cannot be designated as cheapest or top-promoted when "${trueCheapest.providerName}" offers a lower price of ${trueCheapest.normalizedTotalCostVND}₫.`
    );
  }
}

import { describe, expect, it } from 'vitest';
import {
  compareProviderChannels,
  assertCommercialRankingIntegrity,
  CommercialRankingOverrideError,
  ProviderQuoteInput,
} from './directAffiliateComparison';

describe('F43: Direct/Affiliate Provider Comparison', () => {
  const directAirlineQuote: ProviderQuoteInput = {
    providerId: 'vna_direct',
    providerName: 'Vietnam Airlines Official',
    channelType: 'DIRECT_AIRLINE',
    quoteBasis: 'BASE_FARE_ONLY',
    rawQuotedPriceVND: 1_200_000,
    mandatoryTaxesAndFeesVND: 450_000,
    checkedBaggageFeeVND: 0,
    isBaggageIncludedInQuote: true, // VNA includes 23kg
    deepLinkClass: 'DEEP_LINK_EXACT_OFFER',
    deepLinkUrl: 'https://www.vietnamairlines.com/booking/123',
    isCommercialPartner: false,
    observedAt: '2026-10-15T02:00:00Z',
  };

  const highPayingOtaQuote: ProviderQuoteInput = {
    providerId: 'ota_sponsored',
    providerName: 'SuperOTA (Sponsored)',
    channelType: 'OTA_PARTNER',
    quoteBasis: 'TOTAL_INCLUSIVE_NO_BAGGAGE',
    rawQuotedPriceVND: 1_800_000,
    mandatoryTaxesAndFeesVND: 0,
    checkedBaggageFeeVND: 250_000,
    isBaggageIncludedInQuote: false,
    deepLinkClass: 'DEEP_LINK_EXACT_OFFER',
    deepLinkUrl: 'https://superota.com/flight/123?ref=farely_vip',
    isCommercialPartner: true,
    affiliateCommissionRatePercent: 8.0, // High paying partner
    observedAt: '2026-10-15T02:00:00Z',
  };

  const discountOtaQuote: ProviderQuoteInput = {
    providerId: 'trip_discount',
    providerName: 'Trip Discount',
    channelType: 'OTA_PARTNER',
    quoteBasis: 'TOTAL_INCLUSIVE_NO_BAGGAGE',
    rawQuotedPriceVND: 1_550_000,
    mandatoryTaxesAndFeesVND: 0,
    checkedBaggageFeeVND: 0,
    isBaggageIncludedInQuote: true,
    deepLinkClass: 'SEARCH_RESULTS_PREFILLED',
    deepLinkUrl: 'https://trip.com/flights/search',
    isCommercialPartner: false,
    observedAt: '2026-10-15T02:00:00Z',
  };

  it('normalizes total costs and designates the true objective cheapest provider', () => {
    // Direct: 1.2M + 450k = 1.65M
    // High Paying OTA: 1.8M
    // Discount OTA: 1.55M
    const result = compareProviderChannels({
      flightKey: 'VN214_SGN_HAN_20261101',
      quotes: [directAirlineQuote, highPayingOtaQuote, discountOtaQuote],
      requiresCheckedBaggage: false,
    });

    expect(result.objectiveCheapestProviderId).toBe('trip_discount');
    expect(result.channels[0].providerId).toBe('trip_discount');
    expect(result.channels[0].normalizedTotalCostVND).toBe(1_550_000);
    expect(result.channels[1].providerId).toBe('vna_direct');
    expect(result.channels[1].normalizedTotalCostVND).toBe(1_650_000);
    expect(result.channels[2].providerId).toBe('ota_sponsored');
    expect(result.channels[2].normalizedTotalCostVND).toBe(1_800_000);
  });

  it('adjusts total cost when checked baggage is required', () => {
    // With baggage:
    // Direct: 1.2M + 450k + 0 = 1.65M (already included)
    // Discount OTA: 1.55M + 0 = 1.55M (already included)
    // High Paying OTA: 1.8M + 250k = 2.05M
    const result = compareProviderChannels({
      flightKey: 'VN214_SGN_HAN_20261101',
      quotes: [directAirlineQuote, highPayingOtaQuote, discountOtaQuote],
      requiresCheckedBaggage: true,
    });

    const highPaying = result.channels.find((c) => c.providerId === 'ota_sponsored');
    expect(highPaying?.normalizedTotalCostVND).toBe(2_050_000);
    expect(highPaying?.breakdown.baggageFeeVND).toBe(250_000);
  });

  it('passes commercial ranking assertion when promoting the genuine cheapest channel', () => {
    const result = compareProviderChannels({
      flightKey: 'VN214_SGN_HAN_20261101',
      quotes: [directAirlineQuote, discountOtaQuote],
    });

    expect(() =>
      assertCommercialRankingIntegrity('trip_discount', result)
    ).not.toThrow();
  });

  it('throws CommercialRankingOverrideError if a high-commission partner is falsely promoted over cheaper channel', () => {
    const result = compareProviderChannels({
      flightKey: 'VN214_SGN_HAN_20261101',
      quotes: [directAirlineQuote, highPayingOtaQuote, discountOtaQuote],
    });

    // Attempting to assert ota_sponsored (1.8M) as top-promoted cheapest when trip_discount is 1.55M
    expect(() =>
      assertCommercialRankingIntegrity('ota_sponsored', result)
    ).toThrow(CommercialRankingOverrideError);
  });

  it('avoids double taxation when quoteBasis is TOTAL_INCLUSIVE_NO_BAGGAGE or ALL_INCLUSIVE_WITH_BAGGAGE (AUD-10)', () => {
    const inclusiveOtaQuote: ProviderQuoteInput = {
      providerId: 'ota_inclusive',
      providerName: 'Inclusive OTA',
      channelType: 'OTA_PARTNER',
      quoteBasis: 'TOTAL_INCLUSIVE_NO_BAGGAGE',
      rawQuotedPriceVND: 1_600_000,
      mandatoryTaxesAndFeesVND: 400_000, // Disclosed component, already included in 1.6M
      checkedBaggageFeeVND: 200_000,
      isBaggageIncludedInQuote: false,
      deepLinkClass: 'DEEP_LINK_EXACT_OFFER',
      deepLinkUrl: 'https://example.com/inclusive',
      isCommercialPartner: false,
      observedAt: '2026-10-15T02:00:00Z',
    };

    const allInclusiveQuote: ProviderQuoteInput = {
      providerId: 'vna_package',
      providerName: 'Vietnam Airlines Package',
      channelType: 'DIRECT_AIRLINE',
      quoteBasis: 'ALL_INCLUSIVE_WITH_BAGGAGE',
      rawQuotedPriceVND: 1_900_000,
      mandatoryTaxesAndFeesVND: 400_000,
      checkedBaggageFeeVND: 250_000,
      isBaggageIncludedInQuote: true,
      deepLinkClass: 'DEEP_LINK_EXACT_OFFER',
      deepLinkUrl: 'https://vietnamairlines.com/package',
      isCommercialPartner: false,
      observedAt: '2026-10-15T02:00:00Z',
    };

    // Without baggage:
    const resNoBaggage = compareProviderChannels({
      flightKey: 'VN214_SGN_HAN_20261101',
      quotes: [inclusiveOtaQuote, allInclusiveQuote],
      requiresCheckedBaggage: false,
    });

    const otaNoBaggage = resNoBaggage.channels.find((c) => c.providerId === 'ota_inclusive')!;
    // Should NOT be 1.6M + 400k = 2.0M! It must strictly remain 1.6M
    expect(otaNoBaggage.normalizedTotalCostVND).toBe(1_600_000);
    expect(otaNoBaggage.breakdown.mandatoryTaxesAndFeesVND).toBe(400_000);
    expect(otaNoBaggage.breakdown.baseFareVND).toBe(1_200_000);

    const allIncNoBaggage = resNoBaggage.channels.find((c) => c.providerId === 'vna_package')!;
    expect(allIncNoBaggage.normalizedTotalCostVND).toBe(1_900_000);

    // With baggage:
    const resWithBaggage = compareProviderChannels({
      flightKey: 'VN214_SGN_HAN_20261101',
      quotes: [inclusiveOtaQuote, allInclusiveQuote],
      requiresCheckedBaggage: true,
    });

    const otaWithBaggage = resWithBaggage.channels.find((c) => c.providerId === 'ota_inclusive')!;
    // 1.6M raw + 200k baggage = 1.8M (not 1.8M + 400k taxes!)
    expect(otaWithBaggage.normalizedTotalCostVND).toBe(1_800_000);

    const allIncWithBaggage = resWithBaggage.channels.find((c) => c.providerId === 'vna_package')!;
    // Baggage is already included, so total cost remains 1.9M
    expect(allIncWithBaggage.normalizedTotalCostVND).toBe(1_900_000);
  });
});

snapshots.src/domain/farely/personalizedFeedPrivac:
/**
 * F38: Personalized Travel Feed Privacy & Non-Profiling (Tier P2)
 *
 * Requirements:
 * - Solution: Explicit preference opt-in, privacy controls and controlled retention/saved-outcome evaluation.
 * - Acceptance Invariant: No sensitive inference or covert profiling.
 */

export class CovertProfilingViolationError extends Error {
  constructor(message: string) {
    super(`[F38_COVERT_PROFILING_VIOLATION] ${message}`);
    this.name = 'CovertProfilingViolationError';
  }
}

export interface ExplicitUserPreferences {
  isPersonalizationOptedIn: boolean; // Must be explicit; never covert
  homeAirports?: string[];
  preferredAirlines?: string[];
  maxBudgetVND?: number;
  maxStops?: number;
}

export interface FeedCandidateDeal {
  id: string;
  originCode: string;
  destinationCode: string;
  airlineCode: string;
  priceVND: number;
  objectiveDealScore: number;
  stops: number;
}

export interface RankedFeedItem {
  deal: FeedCandidateDeal;
  displayRank: number;
  isPersonalizedPromotion: boolean;
  rankingRationaleVi: string;
}

// Prohibited demographic and covert profiling attributes
const SENSITIVE_PROFILING_KEYS = [
  'inferredIncomeTier',
  'inferredReligion',
  'inferredEthnicity',
  'inferredPoliticalStance',
  'inferredHealthStatus',
  'covertDeviceFingerprint',
  'surveillanceCohortId',
  'inferredMaritalStatus',
  'creditWorthinessScore',
] as const;

/**
 * Validates and cleanses user context, strictly rejecting any covert or sensitive inferences (F38).
 */
export function sanitizePersonalizationContext(contextPayload: Record<string, unknown>): void {
  for (const key of Object.keys(contextPayload)) {
    if (SENSITIVE_PROFILING_KEYS.includes(key as any)) {
      throw new CovertProfilingViolationError(
        `Personalization context contains forbidden sensitive/covert inference key: "${key}". Farely strictly prohibits covert profiling or sensitive demographic inference.`
      );
    }
  }
}

/**
 * Ranks deals for travel feed using strictly explicit preferences.
 * When personalization is disabled or unconsented, falls back to objective deal score.
 */
export function rankFeedWithPrivacyGuarantees(params: {
  deals: FeedCandidateDeal[];
  preferences: ExplicitUserPreferences;
  contextPayload?: Record<string, unknown>;
}): RankedFeedItem[] {
  const { deals, preferences, contextPayload = {} } = params;

  // 1. Invariant check: Assert no covert profiling attributes exist
  sanitizePersonalizationContext(contextPayload);

  if (!deals || deals.length === 0) {
    return [];
  }

  // 2. If user has NOT explicitly opted into personalization, return pure objective ranking
  if (!preferences.isPersonalizationOptedIn) {
    const sorted = [...deals].sort((a, b) => b.objectiveDealScore - a.objectiveDealScore);
    return sorted.map((deal, idx) => ({
      deal,
      displayRank: idx + 1,
      isPersonalizedPromotion: false,
      rankingRationaleVi: `Xếp hạng theo Điểm cơ hội khách quan (#${deal.objectiveDealScore}/100)`,
    }));
  }

  // 3. User opted in: Calculate ranking based ONLY on declared explicit criteria
  const scoredDeals = deals.map((deal) => {
    let score = deal.objectiveDealScore;
    const rationales: string[] = [];

    // Origin airport match
    if (preferences.homeAirports && preferences.homeAirports.includes(deal.originCode)) {
      score += 20;
      rationales.push(`Khởi hành từ sân bay bạn quan tâm (${deal.originCode})`);
    }

    // Airline match
    if (preferences.preferredAirlines && preferences.preferredAirlines.includes(deal.airlineCode)) {
      score += 15;
      rationales.push(`Hãng bay ưu thích (${deal.airlineCode})`);
    }

    // Budget match
    if (preferences.maxBudgetVND && deal.priceVND <= preferences.maxBudgetVND) {
      score += 10;
      rationales.push('Trong ngân sách đã đặt');
    }

    // Stop count filter
    if (preferences.maxStops !== undefined && deal.stops <= preferences.maxStops) {
      score += 5;
      rationales.push('Phù hợp số điểm dừng');
    }

    const isPromoted = rationales.length > 0;
    const rationaleText = isPromoted
      ? `Phù hợp sở thích đã chọn: ${rationales.join(' · ')}`
      : `Điểm cơ hội khách quan (#${deal.objectiveDealScore}/100)`;

    return {
      deal,
      compositeScore: score,
      isPersonalizedPromotion: isPromoted,
      rankingRationaleVi: rationaleText,
    };
  });

  scoredDeals.sort((a, b) => b.compositeScore - a.compositeScore);

  return scoredDeals.map((item, idx) => ({
    deal: item.deal,
    displayRank: idx + 1,
    isPersonalizedPromotion: item.isPersonalizedPromotion,
    rankingRationaleVi: item.rankingRationaleVi,
  }));
}

import { describe, expect, it } from 'vitest';
import {
  rankFeedWithPrivacyGuarantees,
  sanitizePersonalizationContext,
  CovertProfilingViolationError,
  FeedCandidateDeal,
  ExplicitUserPreferences,
} from './personalizedFeedPrivacy';

describe('F38: Personalized Travel Feed Privacy & Non-Profiling', () => {
  const deals: FeedCandidateDeal[] = [
    {
      id: 'deal_han_dad',
      originCode: 'HAN',
      destinationCode: 'DAD',
      airlineCode: 'VN',
      priceVND: 1_200_000,
      objectiveDealScore: 80,
      stops: 0,
    },
    {
      id: 'deal_sgn_bkk',
      originCode: 'SGN',
      destinationCode: 'BKK',
      airlineCode: 'VJ',
      priceVND: 1_500_000,
      objectiveDealScore: 90, // Higher objective score
      stops: 0,
    },
  ];

  it('ranks purely by objective DealScore when personalization is not opted in', () => {
    const preferences: ExplicitUserPreferences = {
      isPersonalizationOptedIn: false,
      homeAirports: ['HAN'], // Even if set, must not be used without opt-in
    };

    const result = rankFeedWithPrivacyGuarantees({ deals, preferences });

    expect(result[0].deal.id).toBe('deal_sgn_bkk'); // 90 > 80
    expect(result[0].isPersonalizedPromotion).toBe(false);
    expect(result[0].rankingRationaleVi).toContain('khách quan');
  });

  it('elevates explicitly matching deals when user explicitly opted in', () => {
    const preferences: ExplicitUserPreferences = {
      isPersonalizationOptedIn: true,
      homeAirports: ['HAN'],
      preferredAirlines: ['VN'],
    };

    const result = rankFeedWithPrivacyGuarantees({ deals, preferences });

    // HAN + VN elevates deal_han_dad (80 + 20 + 15 = 115) over deal_sgn_bkk (90)
    expect(result[0].deal.id).toBe('deal_han_dad');
    expect(result[0].isPersonalizedPromotion).toBe(true);
    expect(result[0].rankingRationaleVi).toContain('Hãng bay ưu thích (VN)');
  });

  it('throws CovertProfilingViolationError when context contains forbidden demographic or covert profiling traits', () => {
    expect(() =>
      sanitizePersonalizationContext({
        inferredIncomeTier: 'HIGH_AFFLUENT',
      })
    ).toThrow(CovertProfilingViolationError);

    expect(() =>
      sanitizePersonalizationContext({
        covertDeviceFingerprint: 'canvas_hash_98124',
      })
    ).toThrow(CovertProfilingViolationError);

    expect(() =>
      sanitizePersonalizationContext({
        inferredReligion: 'BUDDHISM',
      })
    ).toThrow(CovertProfilingViolationError);
  });

  it('throws CovertProfilingViolationError during feed ranking if prohibited context is passed', () => {
    const preferences: ExplicitUserPreferences = {
      isPersonalizationOptedIn: true,
    };

    expect(() =>
      rankFeedWithPrivacyGuarantees({
        deals,
        preferences,
        contextPayload: {
          surveillanceCohortId: 'cohort_demographic_77',
        },
      })
    ).toThrow(CovertProfilingViolationError);
  });
});

