    supportsFlexibleDates: false,
    supportsDirectBooking: true,
    requiresExactDates: true,
    supportedCabinClasses: ['ECONOMY'],
    supportedMarketScopes: ['DOMESTIC', 'INTERNATIONAL'],
    maxAdvanceDays: 30,
    rateLimitPerMinute: 10,
  },
};

export function getProviderCapabilities(providerId: string): ProviderCapabilities | undefined {
  return PROVIDER_CAPABILITY_REGISTRY[providerId.trim().toLowerCase()];
}

export function isProviderSupportingJourneyType(providerId: string, journeyType: JourneyType): boolean {
  const caps = getProviderCapabilities(providerId);
  if (!caps) return false;
  return caps.supportedJourneyTypes.includes(journeyType);
}

export interface IntentProviderCompatibilityResult {
  compatible: boolean;
  providerId: string;
  violations: string[];
}

/**
 * Validates travel intent compatibility with a specific provider.
 * INVARIANT F61: A one-way request MUST NEVER silently become a round-trip request.
 */
export function validateIntentProviderCompatibility(
  providerId: string,
  intent: TravelIntent
): IntentProviderCompatibilityResult {
  const caps = getProviderCapabilities(providerId);
  const violations: string[] = [];

  if (!caps) {
    return {
      compatible: false,
      providerId,
      violations: [`Nhà cung cấp '${providerId}' không tồn tại trong danh mục hệ thống.`],
    };
  }

  // Strict F61 validation: Check journey type
  if (!caps.supportedJourneyTypes.includes(intent.journeyType)) {
    violations.push(
      `Nhà cung cấp '${caps.displayName}' không hỗ trợ hình thức hành trình '${intent.journeyType}'. ` +
      `Yêu cầu '${intent.journeyType}' không bao giờ được tự động chuyển đổi sang loại khác.`
    );
  }

  // Check market scope
  if (!caps.supportedMarketScopes.includes(intent.marketScope)) {
    violations.push(
      `Nhà cung cấp '${caps.displayName}' không hỗ trợ phạm vi thị trường '${intent.marketScope}'.`
    );
  }

  // Check cabin class
  if (!caps.supportedCabinClasses.includes(intent.cabin)) {
    violations.push(
      `Nhà cung cấp '${caps.displayName}' không hỗ trợ hạng vé '${intent.cabin}'.`
    );
  }

  return {
    compatible: violations.length === 0,
    providerId,
    violations,
  };
}

/**
 * Filters a list of provider IDs by compatibility with travel intent.
 * Providers that cannot fulfill the requested journeyType or marketScope are excluded,
 * NEVER coerced.
 */
export function filterProvidersByIntent(
  providerIds: readonly string[],
  intent: TravelIntent
): string[] {
  return providerIds.filter((pid) => {
    const result = validateIntentProviderCompatibility(pid, intent);
    return result.compatible;
  });
}

export interface ProviderSearchQuery {
  providerId: string;
  journeyType: JourneyType;
  origin: string;
  destination: string;
  outboundDate: string;
  returnDate?: string;
  adults: number;
  cabin: CabinClass;
}

/**
 * Builds a typed provider search query strictly adhering to the F61 boundary.
 * Throws an explicit error if a provider cannot handle the requested journey type.
 */
export function createProviderSearchQuery(
  providerId: string,
  intent: TravelIntent
): ProviderSearchQuery {
  const validation = validateIntentProviderCompatibility(providerId, intent);
  if (!validation.compatible) {
    throw new Error(
      `F61 boundary violation: Cannot create provider query for '${providerId}': ${validation.violations.join('; ')}`
    );
  }

  const outboundDate = intent.outbound.exact || intent.outbound.from;
  if (!outboundDate) {
    throw new Error('Travel intent requires at least an exact or starting outbound date');
  }

  // Invariant F61: If journeyType is ONE_WAY, returnDate is strictly undefined
  let returnDate: string | undefined = undefined;
  if (intent.journeyType === 'ROUND_TRIP') {
    returnDate = intent.inbound?.exact || intent.inbound?.from;
    if (!returnDate) {
      throw new Error('Round-trip travel intent requires an inbound return date');
    }
  }

  return {
    providerId,
    journeyType: intent.journeyType,
    origin: intent.originScope.primaryCode,
    destination: intent.destinationScope.primaryCode,
    outboundDate,
    returnDate,
    adults: intent.passengers.adults,
    cabin: intent.cabin,
  };
}

import { describe, it, expect } from 'vitest';
import {
  getProviderCapabilities,
  isProviderSupportingJourneyType,
  validateIntentProviderCompatibility,
  filterProvidersByIntent,
  createProviderSearchQuery,
} from './providerCapabilities.ts';
import { createTravelIntent } from './travelIntent.ts';

describe('F61: Typed Provider Capability Matrix & Journey Type Boundary', () => {
  it('registers canonical providers with typed capabilities', () => {
    const vietjet = getProviderCapabilities('vietjet_direct');
    expect(vietjet).toBeDefined();
    expect(vietjet?.supportedJourneyTypes).toContain('ONE_WAY');
    expect(vietjet?.supportedJourneyTypes).toContain('ROUND_TRIP');

    const charter = getProviderCapabilities('charter_oneway_only');
    expect(charter).toBeDefined();
    expect(charter?.supportedJourneyTypes).toEqual(['ONE_WAY']);

    const promo = getProviderCapabilities('vietjet_promo_roundtrip_only');
    expect(promo).toBeDefined();
    expect(promo?.supportedJourneyTypes).toEqual(['ROUND_TRIP']);
  });

  it('correctly queries journey type support per provider', () => {
    expect(isProviderSupportingJourneyType('vietjet_direct', 'ONE_WAY')).toBe(true);
    expect(isProviderSupportingJourneyType('vietjet_direct', 'ROUND_TRIP')).toBe(true);

    expect(isProviderSupportingJourneyType('charter_oneway_only', 'ONE_WAY')).toBe(true);
    expect(isProviderSupportingJourneyType('charter_oneway_only', 'ROUND_TRIP')).toBe(false);

    expect(isProviderSupportingJourneyType('vietjet_promo_roundtrip_only', 'ONE_WAY')).toBe(false);
    expect(isProviderSupportingJourneyType('vietjet_promo_roundtrip_only', 'ROUND_TRIP')).toBe(true);
  });

  it('F61 Invariant: One-way request NEVER silently becomes round-trip', () => {
    const oneWayIntent = createTravelIntent({
      origin: 'HAN',
      destination: 'SGN',
      journeyType: 'ONE_WAY',
      outboundDate: '2026-11-20',
      adults: 1,
    });

    // Validating against a roundtrip-only provider must fail explicitly, NOT coerce
    const result = validateIntentProviderCompatibility('vietjet_promo_roundtrip_only', oneWayIntent);
    expect(result.compatible).toBe(false);
    expect(result.violations[0]).toContain("không hỗ trợ hình thức hành trình 'ONE_WAY'");
    expect(result.violations[0]).toContain('không bao giờ được tự động chuyển đổi');

    // Attempting to build a provider query must throw, never synthesize return date
    expect(() => {
      createProviderSearchQuery('vietjet_promo_roundtrip_only', oneWayIntent);
    }).toThrowError(/F61 boundary violation/);
  });

  it('creates clean one-way provider query without returnDate when supported', () => {
    const oneWayIntent = createTravelIntent({
      origin: 'HAN',
      destination: 'SGN',
      journeyType: 'ONE_WAY',
      outboundDate: '2026-11-20',
      adults: 2,
    });

    const query = createProviderSearchQuery('vietjet_direct', oneWayIntent);
    expect(query.providerId).toBe('vietjet_direct');
    expect(query.journeyType).toBe('ONE_WAY');
    expect(query.origin).toBe('HAN');
    expect(query.destination).toBe('SGN');
    expect(query.outboundDate).toBe('2026-11-20');
    expect(query.returnDate).toBeUndefined();
    expect(query.adults).toBe(2);
  });

  it('creates clean round-trip provider query preserving outbound and inbound dates', () => {
    const roundTripIntent = createTravelIntent({
      origin: 'HAN',
      destination: 'BKK',
      journeyType: 'ROUND_TRIP',
      outboundDate: '2026-12-01',
      returnDate: '2026-12-10',
      adults: 1,
    });

    const query = createProviderSearchQuery('vietjet_direct', roundTripIntent);
    expect(query.journeyType).toBe('ROUND_TRIP');
    expect(query.outboundDate).toBe('2026-12-01');
    expect(query.returnDate).toBe('2026-12-10');
  });

  it('filters provider pool according to intent compatibility without mutating intent', () => {
    const oneWayIntent = createTravelIntent({
      origin: 'HAN',
